        if m['gene_biotype']"'!='"'protein_coding': continue
        vals=[]
        for x in row[1:]:
            try: v=float(x)
            except ValueError:
                v=float('nan'); missing += 1
            vals.append(v)
            if math.isfinite(v):
                minv=min(minv,v)
                if v<0: neg+=1
