        writer.writerow((result[0], result[1], result[2], "%.17g" % result[3], "%.17g" % result[4]))

weakest = min(results, key=lambda result: result[4])
with open("weakest.txt", "w", newline="") as handle:
    handle.write(weakest[0] + "\n")
